namespace lab::urban {
// Ordered glTF library, generated by tools/UrbanMeshes.py.
enum class MeshId : uint32_t {
    Road108, Intersection12, YellowStripe, Sidewalk108, Curb108,
    OpenDrain, LampPole, LampDiffuser, BrickWall, Vines, VineLeaves,
    DeciduousTrunk, DeciduousLeaves, Conifer, Grass, SnowPatch, Puddle, SkyDome,
    RunoffStrip, DeciduousLOD, ConiferLOD, LampLOD, VinesLOD,
    BlockTerrain, RoadNorth108, YellowNorthStripe,
    SidewalkEastNegative, SidewalkNorthPositive, SidewalkNorthNegative,
    CurbEastNegative, CurbNorthPositive, CurbNorthNegative,
    ContinuousGround, ContinuousGroundLab, RoadRepairEast, RoadRepairNorth,
    RoadEastVariant0, RoadEastVariant1, RoadEastVariant2, RoadEastVariant3,
    RoadNorthVariant0, RoadNorthVariant1, RoadNorthVariant2, RoadNorthVariant3,
    EdgeLinesEast, EdgeLinesNorth,
    StopPost, StopFace, StopWhiteMarkings,
    HydrantBody, HydrantFittings,
    PostesBoxBody, PostesBoxBluePanel, PostesBoxLetters,
    UrbanBasketPole, UrbanBasketGreenSlats,
    ManholeCover, ManholeSeat,
    Count
};
enum class SurfaceMaterial : uint32_t {
    Asphalt, AsphaltPatch, WetAsphalt, YellowLine, Concrete, Brick, Mortar, CastIron,
    Rust, LampEnamel, Bark, PineBark, WinterLeaf, Conifer, Grass,
    ForestLitter, Soil, Snow, Slush, Water, OvercastSky,
    RoadWhite, SignRed, SignWhite, MailRed, MailBlue,
    HydrantRed, ParkGreen, Galvanized,
    Steam, LampGlow, Count
};
struct Library {
    uint32_t meshBase{}, materialBase{};
    bool loaded{};
};

// Each tile contains a 6 x 6 spatial index of 20-metre sectors.
// The render objects remain shared-mesh instances in their authored order:
// the index only decides whether an entire sector needs publication.
struct SpatialIndex {
    static constexpr uint32_t Side=6;
    static constexpr uint32_t Count=Side*Side;
    struct Cell {
        float x{},z{},radius{};
        uint32_t objectCount{};
    };
    std::array<Cell,Count> cells{};
    std::vector<uint8_t> objectCell;
};
SpatialIndex IndexTile(Tile tile,std::span<const RenderObject> objects,const MeshData& meshes);
// Returns false only when the full bounding sphere lies beyond the XR far
// plane plus a safety envelope for nearby light shadows and reflection rays.
bool SectorCanContribute(const SpatialIndex::Cell& sector,Point viewer);
// Add shared mesh/material libraries only once; tile instances contain no
// independent copies of textures or vertices.
Library InstallLibrary(SceneData& scene);
// Static placement for one owned tile. Callers control residency and
// publication; this function never calls Graphics::ReplaceScene.
void AppendTile(SceneData& scene,const Library& library,Tile tile,
                std::vector<uint64_t>* identities=nullptr);
// Capture every emitted object's original 64-bit identity, mesh/material,
// transforms and spatial cell without changing the render-object ABI.
GpuResidentTile DescribeResidentTile(Tile tile,std::span<const RenderObject> objects,
                                    std::span<const uint64_t> identities,
                                    const SpatialIndex& spatial,const Library& library);
} // namespace lab::urban
